(5555159, 802855, 53316, '<td valign="top">ABSOLUTELY STUNNING.  This is an amazing photo... I just have no words to describe how perfect this is and how much I love it.</td>', 'ABSOLUTELY STUNNING.  This is an amazing photo... I just have no words to describe how perfect this is and how much I love it.', '2009-07-02 04:44:26.000000', NULL, 1),
(5555587, 802632, 35602, '<td valign="top">Interesting abstract.  Not sure the image works for me, though.</td>', 'Interesting abstract.  Not sure the image works for me, though.', '2009-07-02 13:32:06.000000', NULL, 1),
(5555591, 802627, 35602, '<td valign="top">Very fine grain, which is probably better for the shot.  Overall I found the composition to not work for me, though your tones are nice.</td>', 'Very fine grain, which is probably better for the shot.  Overall I found the composition to not work for me, though your tones are nice.', '2009-07-02 13:33:22.000000', NULL, 1),
(5555593, 802354, 35602, '<td valign="top">Very dark and forboding.  Nice angle. The use of grain seems to make the entire image kind of disappear into itself so that nothing really seems defined enough.  Perhaps it was too dark.</td>', 'Very dark and forboding.  Nice angle. The use of grain seems to make the entire image kind of disappear into itself so that nothing really seems defined enough.  Perhaps it was too dark.', '2009-07-02 13:35:07.000000', NULL, 1),
(5555598, 802657, 35602, '<td valign="top">Sooo sweet.  Looks like it was hand held.  Nice light on her hair.</td>', 'Sooo sweet.  Looks like it was hand held.  Nice light on her hair.', '2009-07-02 13:36:15.000000', NULL, 1),
(5555606, 802656, 35602, '<td valign="top">Nice shot.  Grain treatment seemed a little too light, though.  I see it in the background, but perhaps a bit of shadowing around the figure would have made the image standout more.</td>', 'Nice shot.  Grain treatment seemed a little too light, though.  I see it in the background, but perhaps a bit of shadowing around the figure would have made the image standout more.', '2009-07-02 13:38:07.000000', NULL, 1),
(5555610, 802617, 35602, '<td valign="top">Plenty of grain, but subject is kind of ho hum.</td>', 'Plenty of grain, but subject is kind of ho hum.', '2009-07-02 13:38:47.000000', NULL, 1),
(5555613, 801773, 35602, '<td valign="top">Very pretty shot.  Grain works nicely along the edges.</td>', 'Very pretty shot.  Grain works nicely along the edges.', '2009-07-02 13:39:23.000000', NULL, 1),
(5555614, 802713, 35602, '<td valign="top">Great background.  Like the brushed look to it.</td>', 'Great background.  Like the brushed look to it.', '2009-07-02 13:39:54.000000', NULL, 1),
(5555617, 802884, 35602, '<td valign="top">Lovely light and grain.  Very impressionistic.</td>', 'Lovely light and grain.  Very impressionistic.', '2009-07-02 13:40:18.000000', NULL, 1),
(5555621, 802410, 35602, '<td valign="top">Nice angle.  Looks like a charcoal drawing.</td>', 'Nice angle.  Looks like a charcoal drawing.', '2009-07-02 13:41:00.000000', NULL, 1),
(5555624, 801869, 35602, '<td valign="top">Definite shows grain.  Subject is not my cup of tea, though.  LIke the way you captured the reflection on the boat though.</td>', 'Definite shows grain.  Subject is not my cup of tea, though.  LIke the way you captured the reflection on the boat though.', '2009-07-02 13:41:50.000000', NULL, 1),
(5555628, 802377, 35602, '<td valign="top">Nice black and white.</td>', 'Nice black and white.', '2009-07-02 13:42:44.000000', NULL, 1),
(5555634, 801315, 35602, '<td valign="top">Nice use of rembrandt style light.  NOt sure the grain did the image justice, though.  Perhaps toning it with a rich brown would have worked better.  Not sure.</td>', 'Nice use of rembrandt style light.  NOt sure the grain did the image justice, though.  Perhaps toning it with a rich brown would have worked better.  Not sure.', '2009-07-02 13:45:02.000000', NULL, 1),
(5555636, 802837, 35602, '<td valign="top">Looks like an old news clip.</td>', 'Looks like an old news clip.', '2009-07-02 13:45:27.000000', NULL, 1),
(5555638, 802222, 35602, '<td valign="top">Title very appropriate.  Definitely a very focused image.</td>', 'Title very appropriate.  Definitely a very focused image.', '2009-07-02 13:46:18.000000', NULL, 1),
(5555643, 802727, 35602, '<td valign="top">Nice overlay.  Composition seems too unbalanced for some reason.  Maybe it is the placement of your woman and child.  Either it is too centered or too much background, but it seems like it doesn''t work as presented.</td>', 'Nice overlay.  Composition seems too unbalanced for some reason.  Maybe it is the placement of your woman and child.  Either it is too centered or too much background, but it seems like it doesn''t work as presented.', '2009-07-02 13:47:53.000000', NULL, 1),
(5555646, 802760, 35602, '<td valign="top">Seems like it was taken through glass which took away from the tonal quality.  Looks very flat and lacking in good highlights and shadows.</td>', 'Seems like it was taken through glass which took away from the tonal quality.  Looks very flat and lacking in good highlights and shadows.', '2009-07-02 13:48:57.000000', NULL, 1),
(5555651, 802518, 35602, '<td valign="top">Very cute.</td>', 'Very cute.', '2009-07-02 13:50:23.000000', NULL, 1),
(5555655, 802650, 35602, '<td valign="top">Nice close up.  Love the grain treatment and color tones.</td>', 'Nice close up.  Love the grain treatment and color tones.', '2009-07-02 13:51:34.000000', NULL, 1),
(5555657, 802730, 35602, '<td valign="top">Looks like a winner to me.</td>', 'Looks like a winner to me.', '2009-07-02 13:52:19.000000', NULL, 1),
(5555661, 802838, 35602, '<td valign="top">Not seeing grain, and composition is very confusing.</td>', 'Not seeing grain, and composition is very confusing.', '2009-07-02 13:53:17.000000', NULL, 1),
(5555664, 802523, 35602, '<td valign="top">I am a sucker for horses.  This is a great shot.</td>', 'I am a sucker for horses.  This is a great shot.', '2009-07-02 13:53:58.000000', NULL, 1),
(5555666, 802230, 35602, '<td valign="top">Very cool.</td>', 'Very cool.', '2009-07-02 13:54:31.000000', NULL, 1),
(5555669, 801308, 35602, '<td valign="top">I am not seeing enough tonal ranges for a black and white.  Image is very low key and low contrast, and also very fuzzy.  I wonder what the color version looks like.  The foreground looks like it could be a beautiful wild garden, but can''t tell in this image.</td>', 'I am not seeing enough tonal ranges for a black and white.  Image is very low key and low contrast, and also very fuzzy.  I wonder what the color version looks like.  The foreground looks like it could be a beautiful wild garden, but can''t tell in this image.', '2009-07-02 13:56:18.000000', NULL, 1),
(5555674, 802614, 35602, '<td valign="top">Great image of urban exploration.  Came out wonderfully.</td>', 'Great image of urban exploration.  Came out wonderfully.', '2009-07-02 13:57:20.000000', NULL, 1),
(5555678, 802857, 35602, '<td valign="top">Hmmm.  Seems really flat.</td>', 'Hmmm.  Seems really flat.', '2009-07-02 13:58:11.000000', NULL, 1),
(5555682, 801827, 35602, '<td valign="top">I love reflected buildings, but using grain for the challenge does not suit this subject at all.  I know it is beautiful without the grain.  Need to think a bit harder when taking your shots.</td>', 'I love reflected buildings, but using grain for the challenge does not suit this subject at all.  I know it is beautiful without the grain.  Need to think a bit harder when taking your shots.', '2009-07-02 13:59:31.000000', NULL, 1),
(5555686, 802566, 63398, '<td valign="top">Really a lovely job done with some pretty substantial grain!....7</td>', 'Really a lovely job done with some pretty substantial grain!....7', '2009-07-02 14:00:25.000000', NULL, 1),
(5555690, 802230, 63398, '<td valign="top">Spooky &amp; cool! Nicely done!.....7</td>', 'Spooky & cool! Nicely done!.....7', '2009-07-02 14:01:33.000000', NULL, 1),
(5555693, 802354, 63398, '<td valign="top">Terrific mood, and nice usage of grain without being overpowering.....7</td>', 'Terrific mood, and nice usage of grain without being overpowering.....7', '2009-07-02 14:02:13.000000', NULL, 1),
(5555694, 802651, 35602, '<td valign="top">Like the way the grain works to make the columbine look brilliant and marvelously clear.  The black and white works really well on this subject.  Great detail.</td>', 'Like the way the grain works to make the columbine look brilliant and marvelously clear.  The black and white works really well on this subject.  Great detail.', '2009-07-02 14:02:13.000000', NULL, 1),
(5555698, 802762, 63398, '<td valign="top">I really like your editing....a LOT!!!....7</td>', 'I really like your editing....a LOT!!!....7', '2009-07-02 14:02:44.000000', NULL, 1),
(5555699, 802650, 63398, '<td valign="top">Nice use of grain for a really vintage feel.....7</td>', 'Nice use of grain for a really vintage feel.....7', '2009-07-02 14:03:06.000000', NULL, 1),
(5555702, 802116, 63398, '<td valign="top">That''s amazing the way they''re in step! Nicely done! LOL!!!.....7</td>', 'That''s amazing the way they''re in step! Nicely done! LOL!!!.....7', '2009-07-02 14:03:58.000000', NULL, 1),
(5555704, 802701, 35602, '<td valign="top">Nice use of light to show the shape of the gears.</td>', 'Nice use of light to show the shape of the gears.', '2009-07-02 14:05:21.000000', NULL, 1),
(5555707, 802793, 35602, '<td valign="top">I think that you must have used a very high iso to get the grain on this.  Not sure it worked to the advantage of the photo, though as I look that lifeguard stand is very defined in comparison to the background.  I think the difference between the grainy background and the sharp lifeguard stand creates a mismatch in the picture.  It seems to definitely be distracting compositionally.</td>', 'I think that you must have used a very high iso to get the grain on this.  Not sure it worked to the advantage of the photo, though as I look that lifeguard stand is very defined in comparison to the background.  I think the difference between the grainy background and the sharp lifeguard stand creates a mismatch in the picture.  It seems to definitely be distracting compositionally.', '2009-07-02 14:07:55.000000', NULL, 1),
(5555709, 802608, 35602, '<td valign="top">Beautiful portrait.  Like the title too.</td>', 'Beautiful portrait.  Like the title too.', '2009-07-02 14:08:30.000000', NULL, 1),
(5555710, 802898, 35602, '<td valign="top">I know the challenge is image grain, but the horrible colors created are definitely at odds in this picture.  Sometimes doing a partial desat to tone down the worse of the color (maybe the green/yellow and the purple) will create a more pleasing image.</td>', 'I know the challenge is image grain, but the horrible colors created are definitely at odds in this picture.  Sometimes doing a partial desat to tone down the worse of the color (maybe the green/yellow and the purple) will create a more pleasing image.', '2009-07-02 14:10:05.000000', NULL, 1),
(5555712, 802495, 35602, '<td valign="top">Wow, gutsy title.  Nice street scene capture of the moment.</td>', 'Wow, gutsy title.  Nice street scene capture of the moment.', '2009-07-02 14:10:53.000000', NULL, 1),
(5555721, 802887, 35602, '<td valign="top">Nothing like personifying a landscape.  You didn''t cut all those down for the picture did you?  Grain was a little heavy for the shot.  The incredible feel of sand which is created with the grain treatment on this image works with some subjects.  I think less silhouette style would work better.  A bit more range in tones would help to even out the image.</td>', 'Nothing like personifying a landscape.  You didn''t cut all those down for the picture did you?  Grain was a little heavy for the shot.  The incredible feel of sand which is created with the grain treatment on this image works with some subjects.  I think less silhouette style would work better.  A bit more range in tones would help to even out the image.', '2009-07-02 14:13:21.000000', NULL, 1),
(5555723, 802572, 35602, '<td valign="top">Great expression.  Nice candid moment.</td>', 'Great expression.  Nice candid moment.', '2009-07-02 14:13:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5555738, 802573, 35602, '<td valign="top">Very pretty.  Like the grass and stones.  Don''t like the distorted people, though.  Actually I find the distortion to be unsettling.  I think there may be a way to legally correct the distortion in advanced editing.  Not well versed in doing that, though.  I am sure somebody knows.</td>', 'Very pretty.  Like the grass and stones.  Don''t like the distorted people, though.  Actually I find the distortion to be unsettling.  I think there may be a way to legally correct the distortion in advanced editing.  Not well versed in doing that, though.  I am sure somebody knows.', '2009-07-02 14:20:26.000000', NULL, 1),
(5555740, 802853, 35602, '<td valign="top">Another great urban exploration image.  Boy I gotta take some of these.</td>', 'Another great urban exploration image.  Boy I gotta take some of these.', '2009-07-02 14:20:52.000000', NULL, 1),
(5555751, 802533, 35602, '<td valign="top">Nice motion stop.  Could use a bit more contrast.  Definitely you need to notice the edges when shooting. See in the upper part of the image?  That shadowing?  Try cropping it out to get rid of the unevenness.  Because the sky is also relatively uninteresting, don''t include so much.  It makes for a tighter and better composition.</td>', 'Nice motion stop.  Could use a bit more contrast.  Definitely you need to notice the edges when shooting. See in the upper part of the image?  That shadowing?  Try cropping it out to get rid of the unevenness.  Because the sky is also relatively uninteresting, don''t include so much.  It makes for a tighter and better composition.', '2009-07-02 14:23:42.000000', NULL, 1),
(5555753, 802788, 35602, '<td valign="top">Fun shot.  Great use of grain.  Like the dodging around the tines as well.</td>', 'Fun shot.  Great use of grain.  Like the dodging around the tines as well.', '2009-07-02 14:24:08.000000', NULL, 1),
(5555754, 802729, 35602, '<td valign="top">Extreme grain on this one.  The colors are what make this so interesting.  Very sketch like.</td>', 'Extreme grain on this one.  The colors are what make this so interesting.  Very sketch like.', '2009-07-02 14:24:14.000000', NULL, 1),
(5555755, 802715, 35602, '<td valign="top">Love the strong geometric angles.  Nice dodging and burning work.</td>', 'Love the strong geometric angles.  Nice dodging and burning work.', '2009-07-02 14:25:14.000000', NULL, 1),
(5555757, 802207, 35602, '<td valign="top">Great abstract and tones.</td>', 'Great abstract and tones.', '2009-07-02 14:25:32.000000', NULL, 1),
(5555758, 802568, 35602, '<td valign="top">Wow, nice high key image.</td>', 'Wow, nice high key image.', '2009-07-02 14:26:14.000000', NULL, 1),
(5555763, 802347, 35602, '<td valign="top">Not really my kind of subject.  Composition doesn''t do much for me.  Image also seems very flat for some reason.  The strongest part of the image seems to be the smokestack.  I like the defined ridges on it and the exposure.</td>', 'Not really my kind of subject.  Composition doesn''t do much for me.  Image also seems very flat for some reason.  The strongest part of the image seems to be the smokestack.  I like the defined ridges on it and the exposure.', '2009-07-02 14:28:07.000000', NULL, 1),
(5555764, 802666, 35602, '<td valign="top">Very steely looking.  I can almost feel the texture of the beams with this shot.  Also, the sky looks very painted and nicely toned.</td>', 'Very steely looking.  I can almost feel the texture of the beams with this shot.  Also, the sky looks very painted and nicely toned.', '2009-07-02 14:29:12.000000', NULL, 1),
(5555775, 801872, 35602, '<td valign="top">Love the purple and the brown.  Nice desat treatment.  Great dof, though the flower could be just a little lighter to pull it even more from the background.</td>', 'Love the purple and the brown.  Nice desat treatment.  Great dof, though the flower could be just a little lighter to pull it even more from the background.', '2009-07-02 14:36:23.000000', NULL, 1),
(5555779, 802456, 35602, '<td valign="top">Woo hoo, taking a chance by using negative filter.  Creates an interesting image.  Makes very striking detail while still allowing the grain to work its magic.</td>', 'Woo hoo, taking a chance by using negative filter.  Creates an interesting image.  Makes very striking detail while still allowing the grain to work its magic.', '2009-07-02 14:38:25.000000', NULL, 1),
(5555780, 802350, 35602, '<td valign="top">Very blank landscape.  Nice colors.  Like the muted highlights in the foreground.</td>', 'Very blank landscape.  Nice colors.  Like the muted highlights in the foreground.', '2009-07-02 14:39:26.000000', NULL, 1),
(5555782, 802409, 35602, '<td valign="top">Awesome use of grain.  Great composition and image.</td>', 'Awesome use of grain.  Great composition and image.', '2009-07-02 14:39:52.000000', NULL, 1),
(5555791, 801906, 35602, '<td valign="top">Without the title I really would have trouble figuring out what this is.  I think it is the way the highlight in the boat kind of runs into the background.  Doesn''t separate enough to be recognizable.  My eye automatically goes to the brightest part of the image so I really don''t see the nice separation on the left that was achieved. That is what you want throughout the whole image.</td>', 'Without the title I really would have trouble figuring out what this is.  I think it is the way the highlight in the boat kind of runs into the background.  Doesn''t separate enough to be recognizable.  My eye automatically goes to the brightest part of the image so I really don''t see the nice separation on the left that was achieved. That is what you want throughout the whole image.', '2009-07-02 14:43:23.000000', NULL, 1),
(5555792, 802435, 35602, '<td valign="top">Well, great focus and detail.  Kind of boring, but the brown tones are well used for this particular style of photo.</td>', 'Well, great focus and detail.  Kind of boring, but the brown tones are well used for this particular style of photo.', '2009-07-02 14:44:26.000000', NULL, 1),
(5555794, 802841, 35602, '<td valign="top">Apt title.  Definitely gives a 40''s feel in the way you composed it.  The feeling I get is a hot dry road, very uncomfortable to drive in, like going across Nevada or something.  Evokes a real emotion.</td>', 'Apt title.  Definitely gives a 40''s feel in the way you composed it.  The feeling I get is a hot dry road, very uncomfortable to drive in, like going across Nevada or something.  Evokes a real emotion.', '2009-07-02 14:46:23.000000', NULL, 1),
(5555799, 801890, 35602, '<td valign="top">Whoa, what a macro.  Wonderful droplet from the mouth.  Quite an interesting use of grain to create an even more repulsive emotion.  That is a good thing.</td>', 'Whoa, what a macro.  Wonderful droplet from the mouth.  Quite an interesting use of grain to create an even more repulsive emotion.  That is a good thing.', '2009-07-02 14:47:50.000000', NULL, 1),
(5555809, 802590, 35602, '<td valign="top">Addams family, move over.</td>', 'Addams family, move over.', '2009-07-02 14:55:37.000000', NULL, 1),
(5555811, 802732, 35602, '<td valign="top">Definitely an image that would look way better without the grain.  Beautiful contrast in the red and white buildings.  Nice reflection, but I don''t like the grain on this one.</td>', 'Definitely an image that would look way better without the grain.  Beautiful contrast in the red and white buildings.  Nice reflection, but I don''t like the grain on this one.', '2009-07-02 14:57:07.000000', NULL, 1),
(5555813, 802865, 35602, '<td valign="top">Nice angle and the sky is gorgeous.</td>', 'Nice angle and the sky is gorgeous.', '2009-07-02 14:57:43.000000', NULL, 1),
(5555815, 802522, 35602, '<td valign="top">Great use of motion blur.  Combine with grain and you have a very artistic and impressionistic style photo.</td>', 'Great use of motion blur.  Combine with grain and you have a very artistic and impressionistic style photo.', '2009-07-02 14:59:10.000000', NULL, 1),
(5555817, 802629, 35602, '<td valign="top">I would have called it Fossilized.  The grain makes it look very much like it is encased in amber.</td>', 'I would have called it Fossilized.  The grain makes it look very much like it is encased in amber.', '2009-07-02 15:00:00.000000', NULL, 1),
(5555818, 802784, 35602, '<td valign="top">Nice composition and very vibrant colors.  Grain is distracting in this one, at least for me.</td>', 'Nice composition and very vibrant colors.  Grain is distracting in this one, at least for me.', '2009-07-02 15:01:02.000000', NULL, 1),
(5555820, 802618, 35602, '<td valign="top">Needs a bit of sharpening I think.  It may be the grain that has toned down the sharpness, though.  I like the use of the darker upper corner to offset the bright yellow flower.</td>', 'Needs a bit of sharpening I think.  It may be the grain that has toned down the sharpness, though.  I like the use of the darker upper corner to offset the bright yellow flower.', '2009-07-02 15:02:54.000000', NULL, 1),
(5555823, 802637, 35602, '<td valign="top">Nice memory shot for you.  Subject could be better.  I like the shadow on this.</td>', 'Nice memory shot for you.  Subject could be better.  I like the shadow on this.', '2009-07-02 15:04:23.000000', NULL, 1),
(5555824, 802360, 35602, '<td valign="top">Very simple. Uses grain well.</td>', 'Very simple. Uses grain well.', '2009-07-02 15:04:42.000000', NULL, 1),
(5555840, 801906, 83313, '<td valign="top">I like the perspective, though the crop seems a little centered to me. The grain works, except in the light area on the lower right, where is seems to be just overlaid on an area of bright highlights.</td>', 'I like the perspective, though the crop seems a little centered to me. The grain works, except in the light area on the lower right, where is seems to be just overlaid on an area of bright highlights.', '2009-07-02 15:26:45.000000', NULL, 1),
(5555849, 802889, 83313, '<td valign="top">Are those multicolored speckles the image grain? I''m not sure if this is a serious entry and you misunderstood the concept, or if this is a wonderful and brilliant spoof.<br/> <br/>I expect this will still end up over a 5, simply because the underlying shot is pretty good. (Looks like a lunar module, rather than a lifeguard stand.)</td>', 'Are those multicolored speckles the image grain? I''m not sure if this is a serious entry and you misunderstood the concept, or if this is a wonderful and brilliant spoof. I expect this will still end up over a 5, simply because the underlying shot is pretty good. (Looks like a lunar module, rather than a lifeguard stand.)', '2009-07-02 15:33:24.000000', NULL, 1),
(5555860, 802167, 83313, '<td valign="top">Image grain and JPEG compression are not the same thing. I hope this is a spoof, or an attempt at the brown, but in case it is a serious entry, here is my usual sermon on JPEG compression *sigh*:<br/> <br/>I see a ton of blocky compression artifacts here. Your file size of only 6k indicates a highly (Severely. So severe, it is in pain) compressed image and that is what is robbing most of the detail and sharpness from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (200k for this one)<br/> <br/>If this is the spoof I think it is, you have my congratulations on a brilliant brown attempt. Much more creative than the more usual coal mine or polar bear in a snowstorm shot. The title fits it nicely as well.</td>', 'Image grain and JPEG compression are not the same thing. I hope this is a spoof, or an attempt at the brown, but in case it is a serious entry, here is my usual sermon on JPEG compression *sigh*: I see a ton of blocky compression artifacts here. Your file size of only 6k indicates a highly (Severely. So severe, it is in pain) compressed image and that is what is robbing most of the detail and sharpness from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (200k for this one) If this is the spoof I think it is, you have my congratulations on a brilliant brown attempt. Much more creative than the more usual coal mine or polar bear in a snowstorm shot. The title fits it nicely as well.', '2009-07-02 15:41:00.000000', NULL, 1),
(5555868, 802427, 83313, '<td valign="top">I may be wrong, but I am guessing this to be the <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=63398" rel="nofollow" target="_blank">NikonJeb</a> entry. It has that Jebbish look to it.</td>', 'I may be wrong, but I am guessing this to be the  NikonJeb entry. It has that Jebbish look to it.', '2009-07-02 15:43:39.000000', NULL, 1),
(5555874, 802650, 83313, '<td valign="top">I''m afraid the grain in this one just looks to me as if it were overlaid on the photo. It really does not seem to flow with the image or enhance it to me.</td>', 'I''m afraid the grain in this one just looks to me as if it were overlaid on the photo. It really does not seem to flow with the image or enhance it to me.', '2009-07-02 15:45:24.000000', NULL, 1),
(5555879, 802900, 83313, '<td valign="top">I''m just not caring for it. Perhaps I don''t have a full appreciation of street photography. I dunno. It comes off to me as excessively busy, with my eye not being led anywhere, except out of the frame.</td>', 'I''m just not caring for it. Perhaps I don''t have a full appreciation of street photography. I dunno. It comes off to me as excessively busy, with my eye not being led anywhere, except out of the frame.', '2009-07-02 15:47:56.000000', NULL, 1),
(5555883, 802514, 83313, '<td valign="top">I''m afraid the grain in this shot just comes off to me as a pattern overlaid on the image, and it does not seem to really help the shot any.</td>', 'I''m afraid the grain in this shot just comes off to me as a pattern overlaid on the image, and it does not seem to really help the shot any.', '2009-07-02 15:49:55.000000', NULL, 1),
(5555887, 802746, 83313, '<td valign="top">I like the use of the criss-cross pattern for the grain. It is different and it suits.</td>', 'I like the use of the criss-cross pattern for the grain. It is different and it suits.', '2009-07-02 15:52:22.000000', NULL, 1),
(5555890, 802824, 83313, '<td valign="top">Almost looks like an illustration in a comic book. Is that why you chose such a title?</td>', 'Almost looks like an illustration in a comic book. Is that why you chose such a title?', '2009-07-02 15:53:56.000000', NULL, 1),
(5555897, 802642, 83313, '<td valign="top">The grain is a bit subtle. Not sure it is doing anything to either help or hinder the image. I do like the starkness of the scene however. The reddish brown chair stands out. My impression is that this is the "time out" chair.</td>', 'The grain is a bit subtle. Not sure it is doing anything to either help or hinder the image. I do like the starkness of the scene however. The reddish brown chair stands out. My impression is that this is the "time out" chair.', '2009-07-02 15:56:59.000000', NULL, 1),
(5555899, 802844, 83313, '<td valign="top">Looks like an illustration from a book.</td>', 'Looks like an illustration from a book.', '2009-07-02 15:57:50.000000', NULL, 1),
(5555901, 802812, 83313, '<td valign="top">Simple, but it really works for me. The grain flows with the image, being part of it, rather than being simply overlaid on top of it. Good use of ambient light and I just love the retro phone. A fave and a high vote for this.</td>', 'Simple, but it really works for me. The grain flows with the image, being part of it, rather than being simply overlaid on top of it. Good use of ambient light and I just love the retro phone. A fave and a high vote for this.', '2009-07-02 16:00:05.000000', NULL, 1),
(5555904, 802834, 83313, '<td valign="top">One of the more original takes on a floral shot that I have seen on DPC. How did you manage to write on the petals without destroying them? Hope you left some notes to appease my curiosity.</td>', 'One of the more original takes on a floral shot that I have seen on DPC. How did you manage to write on the petals without destroying them? Hope you left some notes to appease my curiosity.', '2009-07-02 16:02:00.000000', NULL, 1),
(5555907, 802350, 83313, '<td valign="top">I suppose it is celebrity memorial week on DPC!</td>', 'I suppose it is celebrity memorial week on DPC!', '2009-07-02 16:03:08.000000', NULL, 1),
(5555915, 802743, 83313, '<td valign="top">I''m not sure if there is image grain here, or if it is just the texture of the wall I am seeing.</td>', 'I''m not sure if there is image grain here, or if it is just the texture of the wall I am seeing.', '2009-07-02 16:12:42.000000', NULL, 1),
(5556080, 801308, 83313, '<td valign="top">Not seeing a lot of grain in this shot.</td>', 'Not seeing a lot of grain in this shot.', '2009-07-02 17:35:45.000000', NULL, 1),
(5556082, 801869, 83313, '<td valign="top">I like the subject, though I am not so sure the grainy treatment suits it.  Perhaps in B/W, it might look more like a photo from WWII.</td>', 'I like the subject, though I am not so sure the grainy treatment suits it.  Perhaps in B/W, it might look more like a photo from WWII.', '2009-07-02 17:37:24.000000', NULL, 1),
