(5558673, 801433, 83313, '<td valign="top">Not sure that the grain is suited to this shot for me. Just something about it does not quite work for me.</td>', 'Not sure that the grain is suited to this shot for me. Just something about it does not quite work for me.', '2009-07-04 01:44:54.000000', NULL, 1),
(5558674, 802760, 83313, '<td valign="top">The grain isn''t terribly evident, but I really do like this bear shot.</td>', 'The grain isn''t terribly evident, but I really do like this bear shot.', '2009-07-04 01:47:00.000000', NULL, 1),
(5558678, 802722, 83313, '<td valign="top">I see a lot of grain, but not a lot of grain.</td>', 'I see a lot of grain, but not a lot of grain.', '2009-07-04 01:49:10.000000', NULL, 1),
(5558685, 802728, 83313, '<td valign="top">Not an enormous amount of visible image grain at this size, though I really like this.</td>', 'Not an enormous amount of visible image grain at this size, though I really like this.', '2009-07-04 01:53:25.000000', NULL, 1),
(5558686, 802758, 83313, '<td valign="top">Nice portrait. Not a lot of grain coming across at this size, and perhaps her eyes are pimped a little more than I like. It''s a fine line to walk with the eyes, however.</td>', 'Nice portrait. Not a lot of grain coming across at this size, and perhaps her eyes are pimped a little more than I like. It''s a fine line to walk with the eyes, however.', '2009-07-04 01:55:56.000000', NULL, 1),
(5558691, 802669, 83313, '<td valign="top">Like the shot, the only place I can see the image grain is in the sky.</td>', 'Like the shot, the only place I can see the image grain is in the sky.', '2009-07-04 01:57:39.000000', NULL, 1),
(5558692, 802565, 83313, '<td valign="top"><b>Very</b> cool abstract. I''m curious to know what this really is.</td>', 'Very cool abstract. I''m curious to know what this really is.', '2009-07-04 01:58:55.000000', NULL, 1),
(5558695, 802861, 83313, '<td valign="top">Hard overhead sun is tough to deal with. You have some slightly overexposed areas in this that are taking out some detail. It''s hard to shoot in this kind of light.</td>', 'Hard overhead sun is tough to deal with. You have some slightly overexposed areas in this that are taking out some detail. It''s hard to shoot in this kind of light.', '2009-07-04 02:01:02.000000', NULL, 1),
(5558698, 802826, 83313, '<td valign="top">If you hadn''t said what this is in the title, I would have taken it as an abstract.</td>', 'If you hadn''t said what this is in the title, I would have taken it as an abstract.', '2009-07-04 02:02:32.000000', NULL, 1),
