(5559805, 801433, 50695, '<td valign="top">Terrible title. You should have called this "F L A G" or "Commodore Shakitov"<br/> <br/>Stunning picture, though.</td>', 'Terrible title. You should have called this "F L A G" or "Commodore Shakitov" Stunning picture, though.', '2009-07-05 01:20:00.000000', NULL, 1),
(5559806, 802487, 50695, '<td valign="top">I love how lost she is in her garden. It''s like you''re inside her lost thoughts with her.</td>', 'I love how lost she is in her garden. It''s like you''re inside her lost thoughts with her.', '2009-07-05 01:20:45.000000', NULL, 1),
